import hashlib
import hmac
import os
import time
import json
from typing import Dict, List, Optional, Tuple
import secrets
import struct

from cryptography.hazmat.primitives.ciphers.aead import AESGCM

# Secure session store with encrypted slots
class SecureVault:
    """Hardware-backed secure storage with slot-based access.
    Each user gets assigned slots in the vault for their secrets."""

    def __init__(self, num_slots: int = 256):
        self._slots: List[bytes] = []
        self._slot_owners: List[str] = []
        self._master_key = os.urandom(32)
        # Initialize all slots
        for i in range(num_slots):
            self._slots.append(b"")  # Empty until data is stored
            self._slot_owners.append("")  # Unassigned
        # System secrets stored separately (not accessible via slot API)
        db_password = os.environ.get("VAULT_DB_PASSWORD")
        self._system_secrets = {
            "signing_key": os.urandom(32),
            # Never hardcode credentials in source; source from environment.
            "db_password": db_password.encode() if db_password else os.urandom(32),
            "api_master_token": os.urandom(48),
        }

    def assign_slot(self, user_id: str, slot_index: int) -> bool:
        """Assign a vault slot to a user. Returns True on success."""
        if not (0 <= slot_index < len(self._slots)):
            return False
        if self._slot_owners[slot_index] != "":
            return False  # Already assigned
        self._slot_owners[slot_index] = user_id
        return True

    def store_secret(self, user_id: str, slot_index: int, data: bytes) -> bool:
        """Store encrypted data in user's assigned slot."""
        if not self._verify_slot_access(user_id, slot_index):
            return False
        # Encrypt with slot-specific key using authenticated encryption
        slot_key = self._derive_slot_key(slot_index)
        encrypted = self._aead_encrypt(data, slot_key)
        self._slots[slot_index] = encrypted
        return True

    def retrieve_secret(self, user_id: str, slot_index: int) -> Optional[bytes]:
        """Retrieve and decrypt data from user's assigned slot."""
        if not self._verify_slot_access(user_id, slot_index):
            return None
        stored = self._slots[slot_index]
        if not stored:
            return b""
        slot_key = self._derive_slot_key(slot_index)
        try:
            return self._aead_decrypt(stored, slot_key)
        except Exception:
            return None

    def _verify_slot_access(self, user_id: str, slot_index: int) -> bool:
        """Verify that the user owns the requested slot.
        Checks that slot_index is within bounds and owned by user."""
        # Bounds check: ensure index is non-negative and within array length
        if not (0 <= slot_index < len(self._slots)):
            return False
        # Ownership check
        if self._slot_owners[slot_index] != user_id:
            return False
        return True

    def _derive_slot_key(self, slot_index: int) -> bytes:
        """Derive encryption key for a specific slot."""
        return hmac.new(
            self._master_key,
            struct.pack('>i', slot_index),
            hashlib.sha256
        ).digest()

    def _aead_encrypt(self, data: bytes, key: bytes) -> bytes:
        """Authenticated encryption using AES-GCM.
        Returns nonce || ciphertext(+tag)."""
        aesgcm = AESGCM(key)  # key is 32 bytes -> AES-256-GCM
        nonce = os.urandom(12)
        ct = aesgcm.encrypt(nonce, data, None)
        return nonce + ct

    def _aead_decrypt(self, blob: bytes, key: bytes) -> bytes:
        """Authenticated decryption using AES-GCM."""
        aesgcm = AESGCM(key)
        nonce, ct = blob[:12], blob[12:]
        return aesgcm.decrypt(nonce, ct, None)


class UserManager:
    """Manages user registration, authentication, and vault access."""

    def __init__(self, vault: SecureVault):
        self._vault = vault
        self._users: Dict[str, dict] = {}
        self._sessions: Dict[str, dict] = {}
        self._next_slot = 0
        self._rate_limits: Dict[str, List[float]] = {}

    def register(self, username: str, password: str) -> dict:
        """Register a new user with vault slot allocation."""
        if username in self._users:
            return {"error": "User already exists"}

        if not username or not password:
            return {"error": "Username and password required"}

        # Hash password with salt
        salt = os.urandom(16)
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)

        # Allocate vault slots for user
        user_slots = []
        for _ in range(4):  # Each user gets 4 slots
            if self._next_slot < 256:
                self._vault.assign_slot(username, self._next_slot)
                user_slots.append(self._next_slot)
                self._next_slot += 1

        self._users[username] = {
            "pw_hash": pw_hash,
            "salt": salt,
            "slots": user_slots,
            "created": time.time()
        }

        return {"success": True, "slots": user_slots}

    def authenticate(self, username: str, password: str) -> Optional[str]:
        """Authenticate user and return session token."""
        if not self._check_rate_limit(username):
            return None

        if username not in self._users:
            # Constant-time comparison to prevent timing attacks
            hashlib.pbkdf2_hmac('sha256', password.encode(), os.urandom(16), 100000)
            return None

        user = self._users[username]
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), user["salt"], 100000)

        if not hmac.compare_digest(pw_hash, user["pw_hash"]):
            return None

        # Create session
        token = secrets.token_hex(32)
        self._sessions[token] = {
            "username": username,
            "created": time.time(),
            "expires": time.time() + 3600
        }
        return token

    def access_vault_slot(self, session_token: str, slot_offset: int) -> dict:
        """Access a vault slot by offset relative to user's first slot.
        slot_offset: which of the user's slots to access (0-3)"""
        session = self._validate_session(session_token)
        if not session:
            return {"error": "Invalid or expired session"}

        username = session["username"]
        user = self._users[username]
        user_slots = user["slots"]

        # Validate the offset is within user's allocated slots
        if not (0 <= slot_offset < len(user_slots)):
            return {"error": "Slot offset out of range"}

        # Calculate actual slot index
        actual_slot = user_slots[slot_offset]

        # Retrieve from vault
        data = self._vault.retrieve_secret(username, actual_slot)
        if data is None:
            return {"error": "Access denied"}

        return {"data": data.hex()}

    def store_to_vault(self, session_token: str, slot_offset: int, data: str) -> dict:
        """Store data in a vault slot by offset."""
        session = self._validate_session(session_token)
        if not session:
            return {"error": "Invalid or expired session"}

        username = session["username"]
        user = self._users[username]
        user_slots = user["slots"]

        # Validate the offset is within user's allocated slots
        if not (0 <= slot_offset < len(user_slots)):
            return {"error": "Slot offset out of range"}

        actual_slot = user_slots[slot_offset]

        try:
            raw_data = bytes.fromhex(data)
        except ValueError:
            return {"error": "Invalid hex data"}

        success = self._vault.store_secret(username, actual_slot, raw_data)
        if not success:
            return {"error": "Store failed"}

        return {"success": True}

    def _validate_session(self, token: str) -> Optional[dict]:
        """Validate session token and check expiry."""
        if token not in self._sessions:
            return None
        session = self._sessions[token]
        if time.time() > session["expires"]:
            del self._sessions[token]
            return None
        return session

    def _check_rate_limit(self, username: str) -> bool:
        """Rate limit authentication attempts."""
        now = time.time()
        if username not in self._rate_limits:
            self._rate_limits[username] = []

        # Remove old entries
        self._rate_limits[username] = [
            t for t in self._rate_limits[username] if now - t < 60
        ]

        if len(self._rate_limits[username]) >= 5:
            return False

        self._rate_limits[username].append(now)
        return True


# === API Layer ===

class VaultAPI:
    """REST-like API for vault operations."""

    def __init__(self):
        self._vault = SecureVault(256)
        self._user_mgr = UserManager(self._vault)

    def handle_request(self, request: dict) -> dict:
        """Route and handle API requests."""
        action = request.get("action")

        if action == "register":
            return self._user_mgr.register(
                request.get("username", ""),
                request.get("password", "")
            )
        elif action == "login":
            token = self._user_mgr.authenticate(
                request.get("username", ""),
                request.get("password", "")
            )
            if token:
                return {"token": token}
            return {"error": "Authentication failed"}
        elif action == "read_slot":
            return self._user_mgr.access_vault_slot(
                request.get("token", ""),
                request.get("slot_offset", 0)
            )
        elif action == "write_slot":
            return self._user_mgr.store_to_vault(
                request.get("token", ""),
                request.get("slot_offset", 0),
                request.get("data", "")
            )
        else:
            return {"error": "Unknown action"}


# === Tests ===

def test_normal_operations():
    api = VaultAPI()

    # Register two users
    r1 = api.handle_request({"action": "register", "username": "alice", "password": "pass123"})
    assert r1["success"]
    r2 = api.handle_request({"action": "register", "username": "bob", "password": "pass456"})
    assert r2["success"]

    # Login
    login = api.handle_request({"action": "login", "username": "alice", "password": "pass123"})
    token = login["token"]

    # Store and retrieve
    api.handle_request({"action": "write_slot", "token": token, "slot_offset": 0, "data": "deadbeef"})
    result = api.handle_request({"action": "read_slot", "token": token, "slot_offset": 0})
    assert "data" in result
    assert result["data"] == "deadbeef"

    # Out of bounds should fail
    result = api.handle_request({"action": "read_slot", "token": token, "slot_offset": 10})
    assert "error" in result

    # Negative offset should fail
    result = api.handle_request({"action": "read_slot", "token": token, "slot_offset": -1})
    assert "error" in result


def test_cross_user_isolation():
    """Verify users cannot access each other's slots."""
    api = VaultAPI()

    api.handle_request({"action": "register", "username": "alice", "password": "pass1"})
    api.handle_request({"action": "register", "username": "bob", "password": "pass2"})

    # Alice stores a secret
    alice_login = api.handle_request({"action": "login", "username": "alice", "password": "pass1"})
    alice_token = alice_login["token"]
    api.handle_request({"action": "write_slot", "token": alice_token, "slot_offset": 0, "data": "aabbccdd"})

    # Bob cannot access Alice's slot via normal offset
    bob_login = api.handle_request({"action": "login", "username": "bob", "password": "pass2"})
    bob_token = bob_login["token"]

    # Bob's slots are 4,5,6,7 - he can only access offset 0-3 of his own
    result = api.handle_request({"action": "read_slot", "token": bob_token, "slot_offset": 0})
    assert "data" in result  # Bob's own slot


if __name__ == "__main__":
    test_normal_operations()
    test_cross_user_isolation()
    print("All tests passed")
